txt = "\n".join(L) + "\n"
# ----- cadeado 1: a guarda P18 no texto final
v = GP.violacoes(txt)
assert not v, ("P18 no ESTADO", v[:5])
# ----- cadeado 2: a regra da ordem do 4,44 em cada linha do ESTADO que traz o numero: tem de trazer o p calibrado e a linha dos 5 sigma
falhas = []
for par in txt.split("\n"):
    if z4 in par:
        n = QV.normaliza(par)
        if not (re.search(r"5\s*(?:sigma|\u03c3)", n) and ("e-6" in n or p4.replace("−", "-") in n) and ("alcan" in n)):
            falhas.append(par[:140])
assert not falhas, ("regra da ordem do 4,44 no ESTADO", falhas[:3])
# ----- cadeado 3: varredura das aspas: toda citacao entre « » de 12 caracteres ou mais existe VERBATIM nas falas do operador (cunhagens_13out\*OPERADOR_*), no Atlas ou e' rotulo da cadeia
_norm = lambda s: re.sub(r"\s+", " ", s.replace("’", "'")).strip()
_OPB = " || ".join(_norm(open(p, encoding="utf-8", errors="replace").read()) for p in glob.glob(os.path.join(DL.WK, "cunhagens_13out", "*OPERADOR_*.txt")))
_ROT = {"o teste da única palavra", "sônico e a afinação das cordas", "sonico e a afinacao das cordas", "n/d", "concordo com tudo"}
nao_verb = []
for m in re.finditer("«([^»]{1,700})»", txt):
    fr = _norm(m.group(1)).strip(" .,;:")
    if len(fr) < 12 or fr.lower() in _ROT:
        continue
    if fr.lower() not in _OPB.lower():
        nao_verb.append(fr[:140])
assert not nao_verb, ("citacao nao verbatim no ESTADO", nao_verb[:5])
p = os.path.join(HERE, "ESTADO_V398.md")
if os.path.exists(p):
    os.replace(p, p + ".bak_" + time.strftime("%Y%m%d_%H%M%S") + "_c1")
open(p + ".tmp", "w", encoding="utf-8", newline="\n").write(txt); assert os.path.getsize(p + ".tmp") == len(txt.encode("utf-8")); os.replace(p + ".tmp", p)
print("ESTADO_V398.md", len(txt.encode("utf-8")), "bytes;", len(L), "linhas; sha16", sha(txt.encode("utf-8"))[:16], "| P18 limpa | regra do 4,44 em", sum(1 for par in txt.split("\n") if z4 in par), "linha(s) | aspas verbatim: ok")
